#include "gpu_batch_loss.cuh"
#include <cstdio>
int main(){using namespace tao::dual;try{int n=261,S=4;Vec x(n*S);for(size_t i=0;i<x.size();++i)x[i]=float(int(i%19)-9)*.2f;Device X(x),g(Vec(n*S,.1f)),ref(Vec(n*S,.1f)),loss(S),rl(Vec(S,0));unsigned targets[4]={0,55,260,77},masks[4]={1,0,1,0};unsigned *t,*m;check(cudaMalloc(&t,16));check(cudaMalloc(&m,16));check(cudaMemcpy(t,targets,16,cudaMemcpyHostToDevice));check(cudaMemcpy(m,masks,16,cudaMemcpyHostToDevice));ds_ce_batch<<<S,256>>>(X.p,g.p,loss.p,n,t,m);for(int s=0;s<S;++s)if(masks[s])ds_ce_parallel<<<1,256>>>(X.p+s*n,ref.p+s*n,rl.p+s,n,targets[s],1);check(cudaGetLastError());bool same=g.host()==ref.host()&&loss.host()==rl.host();cudaFree(t);cudaFree(m);if(!same)return 1;printf("PASS batched CE loss/additive gradients match serial; masked slots unchanged\n");return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 2;}}
